// ignore_for_file: avoid_print
import 'dart:io';

/// Generates `lib/features/tech/i18n/gen/{en,ja,vi}.dart` from `FE/src/i18n/*.ts`, so both apps
/// read the same words. Run from `DesktopApp/` after the FE dictionaries change:
///
///   dart run tool/gen_i18n.dart
///
/// `test/tech_i18n_test.dart` fails when the generated files are out of date.
const languages = ['en', 'ja', 'vi'];
const feDir = '../FE/src/i18n';
const outDir = 'lib/features/tech/i18n/gen';

/// The key areas the technician app reads. `n.` holds catalog names, `skip` is a whole key.
const prefixes = [
  'common.', 'err.', 'js.', 'lang.', 'login.', 'n.', 'ot.', 'po.', 'rail.', 'rb.', 'role.', 'td.', 'wk.',
];
const wholeKeys = ['skip', 'co.loading'];

final _entry = RegExp(
  r'''^\s*(?:"([^"]+)"|'([^']+)')\s*:\s*(?:"((?:[^"\\]|\\.)*)"|'((?:[^'\\]|\\.)*)')\s*,?\s*(?://.*)?$''',
);
final _ignored = RegExp(r'''^\s*(?://.*|/\*.*|\*.*|\}.*|import\s.*|export\s.*\{\s*|export\s+type\s.*|)$''');
final _escape = RegExp(r'''\\(u\{[0-9a-fA-F]+\}|u[0-9a-fA-F]{4}|x[0-9a-fA-F]{2}|.)''');

String _unescape(String s) => s.replaceAllMapped(_escape, (m) {
      final e = m[1]!;
      if (e.startsWith('u{')) return String.fromCharCode(int.parse(e.substring(2, e.length - 1), radix: 16));
      if (e.startsWith('u') && e.length == 5) return String.fromCharCode(int.parse(e.substring(1), radix: 16));
      if (e.startsWith('x') && e.length == 3) return String.fromCharCode(int.parse(e.substring(1), radix: 16));
      return switch (e) { 'n' => '\n', 't' => '\t', 'r' => '\r', _ => e };
    });

/// Reads a dictionary of one `"key": "text",` per line. Any other line is an error, so a new
/// way of writing entries fails here instead of silently dropping strings.
Map<String, String> parseDictionary(String source, String name) {
  final out = <String, String>{};
  final lines = source.split('\n');
  for (var i = 0; i < lines.length; i++) {
    final m = _entry.firstMatch(lines[i]);
    if (m != null) {
      out[m[1] ?? m[2]!] = _unescape(m[3] ?? m[4]!);
    } else if (!_ignored.hasMatch(lines[i])) {
      throw FormatException('$name:${i + 1}: cannot read "${lines[i].trim()}"');
    }
  }
  return out;
}

String _dartString(String s) {
  final escaped = s
      .replaceAll(r'\', r'\\')
      .replaceAll("'", r"\'")
      .replaceAll(r'$', r'\$')
      .replaceAll('\n', r'\n')
      .replaceAll('\r', r'\r')
      .replaceAll('\t', r'\t');
  return "'$escaped'";
}

bool wanted(String key) => wholeKeys.contains(key) || prefixes.any(key.startsWith);

/// The generated file for one language.
String renderLanguage(String lang, Map<String, String> dictionary) {
  final b = StringBuffer()
    ..writeln('// Generated by tool/gen_i18n.dart from FE/src/i18n/$lang.ts. Do not edit.')
    ..writeln('// Desktop-only keys live in tech_strings.dart.')
    ..writeln('// ignore_for_file: lines_longer_than_80_chars')
    ..writeln()
    ..writeln('const Map<String, String> ${lang}Strings = {');
  dictionary.forEach((k, v) {
    if (wanted(k)) b.writeln('  ${_dartString(k)}: ${_dartString(v)},');
  });
  b.writeln('};');
  return b.toString();
}

/// Generated text per language, read from the FE dictionaries.
Map<String, String> generateAll() => {
      for (final lang in languages)
        lang: renderLanguage(lang, parseDictionary(File('$feDir/$lang.ts').readAsStringSync(), '$lang.ts')),
    };

void main() {
  generateAll().forEach((lang, text) {
    File('$outDir/$lang.dart').writeAsStringSync(text);
    print('$outDir/$lang.dart');
  });
}
